    // map / choropleth basemap framing must honor --width/--height for static image exports but use
    // the default aspect for responsive HTML, so a non-default static aspect doesn't crop the
    // GeoJSON extent (the wiring shared by build_map_plot and build_choropleth_plot).
    #[test]
    fn fit_dims_honors_image_aspect_only() {
        // HTML ignores --width/--height and always frames for the representative default aspect
        assert_eq!(
            fit_dims(Some(400), Some(900), OutFormat::Html),
            (DEFAULT_IMG_WIDTH, DEFAULT_IMG_HEIGHT)
        );
        // image exports honor an explicit (here narrow/tall) aspect ...
        assert_eq!(fit_dims(Some(400), Some(900), OutFormat::Png), (400, 900));
        // ... and a wide/short one ...
        assert_eq!(fit_dims(Some(1600), Some(300), OutFormat::Svg), (1600, 300));
        // ... falling back to the defaults for whichever dimension is omitted
        assert_eq!(
            fit_dims(None, Some(900), OutFormat::Jpeg),
            (DEFAULT_IMG_WIDTH, 900)
        );

        // the aspect actually changes the fit zoom: a wide extent frames tighter (higher zoom) in a
        // wide-short panel than in a tall-narrow one, so passing the wrong dims would mis-zoom.
        let lats = [30.0, 45.0];
        let lons = [-124.0, -72.0];
        let (_, zoom_wide) = map_center_zoom(&lats, &lons, 0.0, 1600.0, 300.0);
        let (_, zoom_tall) = map_center_zoom(&lats, &lons, 0.0, 300.0, 1600.0);
        assert!(
            zoom_wide > zoom_tall,
            "wide-short panel should frame a wide extent tighter than a tall-narrow one \
             (zoom_wide={zoom_wide}, zoom_tall={zoom_tall})"
        );
    }

    #[test]
    fn first_description_paragraph_skips_markdown_heading() {
        // bold-only heading line (the LLM-generated dictionary case, roborev #3502)
        assert_eq!(
            first_description_paragraph("**Description**\n\nThe real summary sentence."),
            "The real summary sentence."
        );
        // ATX heading
        assert_eq!(
            first_description_paragraph("# Description\n\nThe real summary sentence."),
            "The real summary sentence."
        );
        // no heading: first paragraph returned unchanged (backward compatible)
        assert_eq!(
            first_description_paragraph(
                "First paragraph of the summary.\n\nSecond paragraph is dropped."
            ),
            "First paragraph of the summary."
        );
        // multi-line first paragraph is joined with spaces; only the first paragraph is kept
        assert_eq!(
            first_description_paragraph(
                "**Description**\n\nLine one.\nLine two.\n\n**Notable**\n\n- item"
            ),
            "Line one. Line two."
        );
        // leading blank lines and a heading combined
        assert_eq!(
            first_description_paragraph("\n\n**Description**\n\n\nActual text."),
            "Actual text."
        );
        // a fully-emphasized FIRST paragraph that is a real summary sentence is kept,
        // not mistaken for a heading (roborev #3504): it ends with sentence punctuation.
        assert_eq!(
            first_description_paragraph(
                "**This dataset contains 50,013 records.**\n\nMore detail."
            ),
            "**This dataset contains 50,013 records.**"
        );
        // a long emphasized first line with no terminal punctuation is still kept (not terse).
        assert_eq!(
            first_description_paragraph(
                "*The dataset enumerates every licensed dog across the county each year*\n\nMore."
            ),
            "*The dataset enumerates every licensed dog across the county each year*"
        );
        // empty / heading-only descriptions yield an empty string
        assert_eq!(first_description_paragraph("**Description**"), "");
        assert_eq!(first_description_paragraph("   "), "");
    }

