    fn dict_row(content_type: &str, role: &str, concept: &str, label: &str) -> DictRow {
        DictRow {
            content_type: content_type.to_string(),
            role: role.to_string(),
            concept: concept.to_string(),
            label: label.to_string(),
            ..Default::default()
        }
    }

    #[test]
    fn route_from_concept_maps_namespaces() {
        // coordinates -> map; other geo keys (census_tract, zip, ...) -> dimension bar
        assert_eq!(
            route_from_concept("geo.latitude"),
            Some((Route::MapCoord, None))
        );
        assert_eq!(
            route_from_concept("geo.coordinate_pair"),
            Some((Route::MapCoord, None))
        );
        assert_eq!(
            route_from_concept("geo.census_tract"),
            Some((Route::Dimension, None))
        );
        // state-plane planar coordinates: neither mappable nor a place key -> ProjectedCoord,
        // which charts a distribution only when no point map rendered (see
        // `classify_with_semantics_routes`)
        assert_eq!(
            route_from_concept("geo.crs_stateplane_x"),
            Some((Route::ProjectedCoord, None))
        );
        assert_eq!(
            route_from_concept("geo.crs_stateplane_y"),
            Some((Route::ProjectedCoord, None))
        );
        assert_eq!(
            route_from_concept("nyc.bbl"),
            Some((Route::Dimension, None))
        );
        // temporal
        assert_eq!(
            route_from_concept("time.created_at"),
            Some((Route::Temporal, None))
        );
        // identifiers / PII -> skip
        assert_eq!(
            route_from_concept("id.surrogate_key"),
            Some((Route::Skip, None))
        );
        assert_eq!(route_from_concept("pii.email"), Some((Route::Skip, None)));
        // measures: amount/count/money additive (Sum), ratio averaged (Mean)
        assert_eq!(
            route_from_concept("measure.amount"),
            Some((Route::Measure, Some(Agg::Sum)))
        );
        assert_eq!(
            route_from_concept("measure.count"),
            Some((Route::Measure, Some(Agg::Sum)))
        );
        // money is covered by the namespace's catch-all arm, deliberately: a currency-denominated
        // amount aggregates exactly like any other additive quantity.
        assert_eq!(
            route_from_concept("measure.money"),
            Some((Route::Measure, Some(Agg::Sum)))
        );
        assert_eq!(
            route_from_concept("measure.ratio"),
            Some((Route::Measure, Some(Agg::Mean)))
        );
        // unknown namespace / bare unknown -> None (fall through to role)
        assert_eq!(route_from_concept("weather.temp"), None);
        assert_eq!(route_from_concept("unknown"), None);
    }

    #[test]
    fn intensive_measure_detection() {
        // intensive quantities -> averaged, matched by label or field
        assert!(is_intensive_measure(
            "Average Annual Temperature (\u{b0}C)",
            "avg_annual_temp_c"
        ));
        assert!(is_intensive_measure("Elevation", "elevation_m"));
        assert!(is_intensive_measure("Literacy", "literacy_pct"));
        assert!(is_intensive_measure("Happiness Index", "happiness_index"));
        assert!(is_intensive_measure("Population Density", "pop_density"));
        // additive amounts/counts stay additive
        assert!(!is_intensive_measure(
            "Metro Population (millions)",
            "metro_population_m"
        ));
        assert!(!is_intensive_measure("Revenue", "revenue"));
        assert!(!is_intensive_measure("Packages", "packages"));
        assert!(!is_intensive_measure("Order Count", "order_count"));
        // a COUNT wins over an embedded intensive token — it is additive by definition
        assert!(!is_intensive_measure(
            "Review Score Count",
            "review_score_count"
        ));
        assert!(!is_intensive_measure("Index Count", "index_count"));
        assert!(!is_intensive_measure("Number of Ratings", "num_ratings"));
        // camelCase / PascalCase count fields are recognized even with an empty/unhelpful label
        assert!(!is_intensive_measure("", "reviewScoreCount"));
        assert!(!is_intensive_measure("", "indexCount"));
        assert!(!is_intensive_measure("", "numRatings"));
        // the count guard is token-aware: intensive fields that merely EMBED "count" as a
        // substring (discount, account, county) are still detected as intensive, in snake_case
        // and camelCase alike
        assert!(is_intensive_measure("Discount", "discount_pct"));
        assert!(is_intensive_measure("Account Score", "account_score"));
        assert!(is_intensive_measure("County Index", "county_index"));
        assert!(is_intensive_measure("", "discountPct"));
        assert!(is_intensive_measure("", "accountScore"));
    }

    #[test]
    fn derive_semantics_averages_intensive_measure() {
        let numeric = stat("Float", 300, Some(0.9));
        // temperature tagged as an additive amount by the coarse vocab -> downgraded to Mean
        let temp = derive_semantics(
            &numeric,
            Some(&dict_row(
                "",
                "measure",
                "measure.amount",
                "Average Annual Temperature (\u{b0}C)",
            )),
        );
        assert_eq!(temp.route, Route::Measure);
        assert_eq!(temp.agg, Some(Agg::Mean));
        // a genuine additive amount keeps Sum
        let pop = derive_semantics(
            &numeric,
            Some(&dict_row(
                "",
                "measure",
                "measure.amount",
                "Metro Population",
            )),
        );
        assert_eq!(pop.agg, Some(Agg::Sum));
        // an explicit measure.count stays additive even when its label embeds an intensive token
        // ("score"/"index") — a count is summed, never averaged.
        let counts = stat("Integer", 300, Some(0.9));
        let score_count = derive_semantics(
            &counts,
            Some(&dict_row(
                "",
                "measure",
                "measure.count",
                "Review Score Count",
            )),
        );
        assert_eq!(score_count.agg, Some(Agg::Sum));
    }

    #[test]
    fn route_from_content_type_legacy_mapping() {
        assert_eq!(route_from_content_type("category").0, Route::Dimension);
        assert_eq!(route_from_content_type("state_abbr").0, Route::Dimension);
        assert_eq!(route_from_content_type("latitude").0, Route::MapCoord);
        // temporal tokens, with/without an strftime or length suffix
        assert_eq!(route_from_content_type("date").0, Route::Temporal);
        assert_eq!(
            route_from_content_type("datetime:%Y-%m-%dT%H:%M:%S").0,
            Route::Temporal
        );
        assert_eq!(route_from_content_type("duration:3600").0, Route::Temporal);
        // identifiers / PII / free-text -> skip
        assert_eq!(route_from_content_type("unique_id").0, Route::Skip);
        assert_eq!(route_from_content_type("email").0, Route::Skip);
        assert_eq!(route_from_content_type("free_text").0, Route::Skip);
        // explicit / empty -> defer to stats
        assert_eq!(route_from_content_type("unknown").0, Route::Defer);
        assert_eq!(route_from_content_type("").0, Route::Defer);
    }

    #[test]
    fn route_from_content_type_maps_money_to_measure() {
        // `money` is the vocabulary's only numeric token and the only content_type that carries
        // an aggregation. Without its own arm the catch-all would Skip the column, so a
        // dictionary carrying content_type but no concept would drop every money column.
        assert_eq!(
            route_from_content_type("money"),
            (Route::Measure, Some(Agg::Sum))
        );
        // the sibling token names the currency rather than holding an amount: still a dimension.
        assert_eq!(
            route_from_content_type("currency_code"),
            (Route::Dimension, None)
        );
    }

    #[test]
    fn dict_dmy_preference_reads_the_declared_date_format() {
        let with_ct = |ct: &str| DictRow {
            content_type: ct.to_string(),
            ..DictRow::default()
        };

        // no dictionary row at all -> fall back to the env preference
        assert_eq!(dict_dmy_preference(None), None);

        // declared month-first / day-first formats are authoritative
        assert_eq!(
            dict_dmy_preference(Some(&with_ct("date:%m/%d/%Y"))),
            Some(false)
        );
        assert_eq!(
            dict_dmy_preference(Some(&with_ct("date:%d/%m/%Y"))),
            Some(true)
        );
        // the format's own colons must not truncate it
        assert_eq!(
            dict_dmy_preference(Some(&with_ct("datetime:%m/%d/%Y %I:%M:%S %p"))),
            Some(false)
        );
        // content_type is stored verbatim, so leading whitespace must be trimmed
        assert_eq!(
            dict_dmy_preference(Some(&with_ct("  datetime:%m/%d/%Y %I:%M:%S %p  "))),
            Some(false)
        );

        // no actionable preference -> fall back to the env preference
        assert_eq!(dict_dmy_preference(Some(&with_ct("date"))), None);
        assert_eq!(dict_dmy_preference(Some(&with_ct("date:"))), None);
        assert_eq!(dict_dmy_preference(Some(&with_ct("date:%Y-%m-%d"))), None);
        assert_eq!(dict_dmy_preference(Some(&with_ct("date:%Q"))), None); // invalid strftime
        assert_eq!(dict_dmy_preference(Some(&with_ct("time:%H:%M"))), None); // not date/datetime
        assert_eq!(dict_dmy_preference(Some(&with_ct("unknown"))), None);
        assert_eq!(dict_dmy_preference(Some(&with_ct(""))), None);
    }

    #[test]
    fn derive_semantics_precedence_and_label() {
        // no dictionary row -> Defer (stats-only behavior unchanged)
        assert_eq!(
            derive_semantics(&stat("Integer", 5, None), None).route,
            Route::Defer
        );

        // concept beats a defaulted `measure` role: a numeric census_tract that describegpt left
        // role=measure is still routed to a Dimension bar by its geo.census_tract concept.
        let tract = stat("Integer", 33, Some(0.00003));
        let row = dict_row("", "measure", "geo.census_tract", "Census Tract");
        let sem = derive_semantics(&tract, Some(&row));
        assert_eq!(sem.route, Route::Dimension);
        assert_eq!(sem.label, "Census Tract"); // label carried for the panel title

        // role used when concept is absent/unknown
        let r = derive_semantics(
            &stat("String", 8, Some(0.01)),
            Some(&dict_row("", "dimension", "", "")),
        );
        assert_eq!(r.route, Route::Dimension);

        // content_type used when neither concept nor role resolve
        let c = derive_semantics(
            &stat("Float", 99, Some(0.5)),
            Some(&dict_row("latitude", "", "", "")),
        );
        assert_eq!(c.route, Route::MapCoord);

        // all-empty dictionary row -> Defer, but the label still rides along
        let d = derive_semantics(
            &stat("String", 9, Some(0.02)),
            Some(&dict_row("", "", "", "Notes")),
        );
        assert_eq!(d.route, Route::Defer);
        assert_eq!(d.label, "Notes");
    }

    fn csem(concept: &str) -> ColSemantics {
        ColSemantics {
            concept: concept.to_string(),
            ..Default::default()
        }
    }

    // a numeric measure stat with an explicit coefficient of variation (for the statistical
    // hover-combination picker).
    fn measure_stat(cv: f64) -> crate::cmd::stats::StatsData {
        crate::cmd::stats::StatsData {
            r#type: "Float".to_string(),
            cardinality: 100,
            uniqueness_ratio: Some(0.5),
            cv: Some(cv),
            ..Default::default()
        }
    }

    #[test]
    fn lorenz_curve_all_equal_is_diagonal() {
        // a perfectly equal distribution traces the equality diagonal: share == pop at every point
        let (pop, share) = lorenz_curve(vec![5.0; 4]).unwrap();
        assert_eq!(pop.len(), share.len());
        for (p, s) in pop.iter().zip(&share) {
            assert!(
                (p - s).abs() < 1e-12,
                "equal dist should lie on the diagonal"
            );
        }
        assert_eq!((pop[0], share[0]), (0.0, 0.0));
        assert!((pop.last().unwrap() - 1.0).abs() < 1e-12);
        assert!((share.last().unwrap() - 1.0).abs() < 1e-12);
    }

    #[test]
    fn lorenz_curve_max_inequality_hugs_axis() {
        // one entity holds everything: the bottom (n-1)/n of records hold 0% of the total, so the
        // curve hugs the x-axis then jumps to (1,1) — maximal inequality. Zeros are legitimate.
        let (pop, share) = lorenz_curve(vec![0.0, 0.0, 0.0, 100.0]).unwrap();
        let last = share.len() - 1;
        assert_eq!(share[last - 1], 0.0);
        assert!((share[last] - 1.0).abs() < 1e-12);
        assert!((pop[last] - 1.0).abs() < 1e-12);
    }

    #[test]
    fn lorenz_curve_rejects_degenerate() {
        assert!(lorenz_curve(vec![]).is_none());
        assert!(lorenz_curve(vec![42.0]).is_none()); // a single value can't form a curve
        assert!(lorenz_curve(vec![0.0, 0.0, 0.0]).is_none()); // zero total
    }

    #[test]
    fn lorenz_curve_thins_to_cap() {
        // a large column is thinned to at most LORENZ_CURVE_MAX_POINTS vertices, endpoints kept
        let values: Vec<f64> = (1..=(LORENZ_CURVE_MAX_POINTS as u32 * 3))
            .map(f64::from)
            .collect();
        let (pop, share) = lorenz_curve(values).unwrap();
        assert!(pop.len() <= LORENZ_CURVE_MAX_POINTS);
        assert_eq!((pop[0], share[0]), (0.0, 0.0));
        assert!((pop.last().unwrap() - 1.0).abs() < 1e-12);
        assert!((share.last().unwrap() - 1.0).abs() < 1e-12);
    }

    #[test]
    fn is_inequality_candidate_gates() {
        let stat = |field: &str, gini: Option<f64>| crate::cmd::stats::StatsData {
            r#type: "Float".to_string(),
            field: field.to_string(),
            cardinality: 100,
            gini_coefficient: gini,
            ..Default::default()
        };
        let sem = |agg: Option<Agg>, label: &str| ColSemantics {
            route: Route::Measure,
            agg,
            label: label.to_string(),
            ..Default::default()
        };

        // dictionary additive amount + high Gini -> candidate
        assert!(is_inequality_candidate(
            &sem(Some(Agg::Sum), "revenue"),
            &stat("revenue", Some(0.62))
        ));
        // dictionary intensive (ratio -> Mean) -> never a candidate, whatever the Gini
        assert!(!is_inequality_candidate(
            &sem(Some(Agg::Mean), "growth_rate"),
            &stat("growth_rate", Some(0.90))
        ));
        // no dictionary: additive-looking field name + high Gini -> candidate
        assert!(is_inequality_candidate(
            &sem(None, ""),
            &stat("net_worth", Some(0.75))
        ));
        // no dictionary: intensive field name (temperature) -> not a candidate
        assert!(!is_inequality_candidate(
            &sem(None, ""),
            &stat("avg_temperature", Some(0.75))
        ));
        // Gini below the threshold -> not a candidate
        assert!(!is_inequality_candidate(
            &sem(Some(Agg::Sum), "revenue"),
            &stat("revenue", Some(0.40))
        ));
        // Gini absent (plain viz smart, no --smarter) -> never a candidate
        assert!(!is_inequality_candidate(
            &sem(Some(Agg::Sum), "revenue"),
            &stat("revenue", None)
        ));

        // no dictionary: a skewed near-unique numeric ID/code must NOT get a Lorenz panel even at
        // high Gini (the id/code/key NAME excludes it — the Gini gate alone would not).
        assert!(!is_inequality_candidate(
            &sem(None, ""),
            &stat("customer_id", Some(0.72))
        ));
        assert!(!is_inequality_candidate(
            &sem(None, ""),
            &stat("productCode", Some(0.72))
        ));
        // FLAGSHIP (must not regress): a non-id-named additive amount with high Gini stays a
        // candidate on the stats-only path even though such a column is typically near-unique.
        assert!(is_inequality_candidate(
            &sem(None, ""),
            &stat("population", Some(0.60))
        ));
        // a dictionary-tagged additive measure is NEVER excluded by the id-name heuristic (the
        // name guard is stats-only): an explicit Agg::Sum wins even with an id-ish name.
        assert!(is_inequality_candidate(
            &sem(Some(Agg::Sum), "grant_id"),
            &stat("grant_id", Some(0.60))
        ));
    }

    #[test]
    fn is_identifier_name_token_boundary() {
        // id/code/key/uuid tokens (incl. camelCase + suffixes) are identifiers
        assert!(is_identifier_name("", "customer_id"));
        assert!(is_identifier_name("Customer ID", "customerId"));
        assert!(is_identifier_name("", "product_code"));
        assert!(is_identifier_name("", "order_key"));
        assert!(is_identifier_name("", "record_uuid"));
        assert!(is_identifier_name("", "guid"));
        // numbered twins: a trailing digit run is stripped per token before matching
        assert!(is_identifier_name("", "customer_id2"));
        assert!(is_identifier_name("", "code1"));
        assert!(is_identifier_name("", "productCode2"));
        assert!(is_identifier_name("", "order_key3"));
        // substrings inside real words must NOT trip it (token-boundary, not substring)
        assert!(!is_identifier_name("", "grid"));
        assert!(!is_identifier_name("", "medicaid_payment"));
        assert!(!is_identifier_name("", "decode_ratio"));
        assert!(!is_identifier_name("County", "county"));
        assert!(!is_identifier_name("", "population"));
        assert!(!is_identifier_name("Net Worth", "net_worth"));
        // a digit-suffixed non-identifier token must still be admitted (co2 -> "co", not an id)
        assert!(!is_identifier_name("", "co2_emissions"));
    }

    #[test]
    fn select_map_identifier_dictionary_beats_stats() {
        // idx0 has an id.* concept; idx3 is a near-unique String. The dictionary concept wins.
        let stats = vec![
            stat("Integer", 1000, Some(0.99)), // 0: id column
            stat("Float", 900, Some(0.5)),     // 1: lat
            stat("Float", 900, Some(0.5)),     // 2: lon
            stat("String", 1000, Some(0.99)),  // 3: a near-unique name
        ];
        let sems = vec![
            csem("id.natural_key"),
            csem("geo.latitude"),
            csem("geo.longitude"),
            csem(""),
        ];
        assert_eq!(select_map_identifier(&stats, &sems, None, 1, 2), Some(0));
    }

    #[test]
    fn select_map_identifier_name_like_concept() {
        // no id.* concept -> a name-like concept (geo.city) is the identifier.
        let stats = vec![
            stat("Float", 9, Some(0.5)),   // 0: lat
            stat("Float", 9, Some(0.5)),   // 1: lon
            stat("String", 50, Some(0.6)), // 2: city
            stat("Integer", 5, Some(0.1)), // 3: a code
        ];
        let sems = vec![
            csem("geo.latitude"),
            csem("geo.longitude"),
            csem("geo.city"),
            csem(""),
        ];
        assert_eq!(select_map_identifier(&stats, &sems, None, 0, 1), Some(2));
    }

