    #[test]
    fn map_pan_bounds_pads_and_clamps() {
        // a tight NYC-ish cluster yields a padded box (>= the data extent, still within valid
        // lat/lon) that includes an outlier passed in a second coordinate group
        let bounds = map_pan_bounds(&[
            (
                [40.70_f64, 40.80].as_slice(),
                [-74.02_f64, -73.95].as_slice(),
            ),
            ([41.50_f64].as_slice(), [-73.50_f64].as_slice()),
        ])
        .expect("a well-formed local extent yields bounds");
        let v = serde_json::to_value(&bounds).unwrap();
        // south below the min lat, north above the max lat (outlier included)
        assert!(v["south"].as_f64().unwrap() < 40.70);
        assert!(v["north"].as_f64().unwrap() > 41.50);
        assert!(v["west"].as_f64().unwrap() < -74.02);
        assert!(v["east"].as_f64().unwrap() > -73.50);
        // clamped to valid ranges
        assert!(v["south"].as_f64().unwrap() >= -90.0);
        assert!(v["north"].as_f64().unwrap() <= 90.0);
    }

    #[test]
    fn map_pan_bounds_skips_global_and_empty() {
        // near-global longitude span (or antimeridian-crossing) -> no constraint
        assert!(
            map_pan_bounds(&[([10.0_f64, -10.0].as_slice(), [-170.0_f64, 170.0].as_slice())])
                .is_none()
        );
        // empty / all-nonfinite clouds -> no constraint
        assert!(map_pan_bounds(&[([].as_slice(), [].as_slice())]).is_none());
        assert!(map_pan_bounds(&[([f64::NAN].as_slice(), [f64::NAN].as_slice())]).is_none());
    }

    #[test]
    fn map_center_zoom_centers_on_bounding_box() {
        // a tight cluster around (40, -75) centers there and zooms in
        let lats = [39.9, 40.1, 40.0];
        let lons = [-75.1, -74.9, -75.0];
        let (center, zoom) = map_center_zoom(&lats, &lons, 0.0, 1000.0, 600.0);
        let v = serde_json::to_value(&center).unwrap();
        // the centre latitude is the MERCATOR midpoint, not the arithmetic one: the zoom is
        // fitted in Mercator y, so the centre has to be taken in the same space or the box is not
        // actually centred in the viewport (visible as a clipped poleward edge on tall extents).
        // Over a 0.2-degree cluster the two agree to ~1e-5, hence the loosened tolerance here plus
        // the exact assertion below.
        assert!((v["lat"].as_f64().unwrap() - 40.0).abs() < 1e-3);
        assert!((v["lat"].as_f64().unwrap() - mercator_lat_center(39.9, 40.1)).abs() < 1e-12);
        // longitude is linear in Mercator, so it stays the exact arithmetic midpoint
        assert!((v["lon"].as_f64().unwrap() - (-75.0)).abs() < 1e-9);
        // small span -> high zoom; large span -> low zoom. Use a genuinely wide (non-wrapping)
        // longitude range so this exercises the plain bounding-box path, not antimeridian wrap.
        let (_, world_zoom) = map_center_zoom(&[-60.0, 70.0], &[-80.0, 80.0], 0.0, 1000.0, 600.0);
        assert!(
            zoom > world_zoom,
            "tight cluster should zoom in more than world"
        );
    }

